"""Unit 5: Tagalog Basic Course, Semester I, Unit 1, Chapter 1, Lesson 5: Greetings, Courtesies, and Introductions.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (Teacher Edition, November 2020).
Audio, video, pair work and the blank-writing parts are left out; the book's own answer keys are used where it prints
them, and the English notes are mine."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


# ------------------------------------------------------------------ 1 greetings and courtesies (passage A)
_PAS_A = [("Pia", "Mano po, ’Nay.", "Bless me, Mother."), ("Mother", "Kaawaan ka ng Diyos, anak. Sino sila?", "God bless you, child. Who are they?"), ("Pia", "Mga kaibigan ko po, sina Ding at Liz.", "My friends, sir/ma’am, Ding and Liz."), ("Mother", "Kumusta kayo?", "How are you?"), ("Ding", "Ayos lang po kami. Kamusta po kayo?", "We are fine, ma’am. How are you?"), ("Mother", "Mabuti naman. Halikayo, kain tayo.", "Fine. Come, let’s eat.")]
_VA = [("’Nay", "Mother (short for Nanay)"), ("Mano po.", "Bless me."), ("Kaawaan ka ng Diyos.", "God bless you."), ("anak", "(somebody’s) child"), ("sila", "they"), ("mga kaibigan", "friends"), ("kayo", "you (plural)"), ("ko", "my"), ("mabuti naman", "fine, good"), ("ayos lang", "just fine"), ("tayo", "we (inclusive)"), ("Halikayo", "Come here"), ("kain", "eat"), ("sa iyo", "to you"), ("ikaw", "you"), ("ka", "you")]
_CK = [("What courtesy did Pia use to address her mother?", "Mano po, or putting her mother’s hand on her forehead."), ("What two questions did the mother ask?", "Who are they? and How are you (plural)?"), ("Who is with Pia?", "Pia’s friends Ding and Liz."), ("What courtesy did Pia’s friends use with her mother?", "The use of po, kayo po and Kamusta po kayo.")]
L1 = lesson(
    "C1 L5 · Introducing friends to your mother: mano po",
    "Mano po, ’Nay · Mga kaibigan ko po · Kumusta kayo? · Halikayo, kain tayo",
    requires=[],
    cards=[
        card("Getting started", "The book shows a video of a man introducing his friend to his grandmother and asks what body language you notice and how greetings and courtesies show themselves (the video is left out)."),
        card("Passage A: a woman introduces her friends to her mother", "", examples=dlg(_PAS_A)),
        card("Culture note: mano po and hospitality", "Mano po (literally “your hand, sir/ma’am”) is a traditional sign of respect. You say it while putting an elder’s right hand to your forehead. The response is Kaawaan ka ng Diyos (literally “May God have mercy on you”, which in this context means “God bless you”). Filipinos are gracious hosts and are known for their hospitality; inviting visitors to eat is normal, as the mother does here."),
        card("Notes", "Halikayo is a contraction of halika (come) and kayo (you). Halikayo, kain tayo means “Come, let’s eat.” Kayo means “you, plural” when Pia’s friend is spoken to (Kumusta kayo?) and “you, singular polite” when the mother is spoken to (Kamusta po kayo?)."),
        card("New words", "", tables=[ttable(_VA)]),
        card("Comprehension check (Passage A, the book’s key)", "", tables=[table(["Question", "Answer"], [list(r) for r in _CK], say=[])]),
        card("Activities left out", "The video of Getting Started."),
    ],
    exercises=uniq(
        both_q(_VA)
        + tr_q([(t, e) for _, t, e in _PAS_A])
        + [M(q, a, [x for _, x in _CK if x != a], a) for q, a in _CK]
        + [M("What is the answer to Mano po?", "Kaawaan ka ng Diyos.", ["Ingat ka.", "Mabuti naman.", "Halikayo."], "God bless you."), M("What does mano po literally mean?", "Your hand, sir/ma’am", ["Good morning", "Thank you", "Come in"], "A sign of respect."), M("What does the mother do after the greeting?", "Invites them to eat", ["Says goodbye", "Asks their names", "Gives them a gift"], "Halikayo, kain tayo."), M("What does Halikayo come from?", "halika + kayo", ["halika + tayo", "hali + ako", "halik + sila"], "Come + you."), M("Who is the speaker of Kayo in Kumusta kayo? (the mother to the friends)?", "More than one person", ["One young person", "Herself", "A teacher"], "Kayo is plural."), M("In Kamusta po kayo? to the mother, kayo means", "you, singular polite", ["you, plural", "we", "they"], "Kayo with po shows respect."), M("Which hand is placed on the forehead in mano po?", "The elder’s right hand", ["The elder’s left hand", "Your own hand", "Both hands"], "The elder’s right hand."), M("Why does the mother invite the guests to eat?", "Filipinos are gracious hosts", ["It is a test", "It is the end of class", "It is a rule"], "Hospitality.")]
        + [F("Mano ___, ’Nay. (polite)", "po", ["ko", "ba"], "Mano po."), F("___ ka ng Diyos, anak.", "Kaawaan", ["Halikayo", "Ingat"], "Kaawaan ka ng Diyos."), F("Mga kaibigan ___ po. (my)", "ko", ["ka", "kayo"], "ko = my."), F("Ayos lang po ___. (we are, excluding the mother)", "kami", ["tayo", "sila"], "Kami."), F("Halikayo, kain ___. (let’s eat)", "tayo", ["kami", "sila"], "Tayo includes the speaker and the person spoken to."), F("Sino ___? (they)", "sila", ["siya", "kami"], "Sino sila?")]
    ),
)

# ------------------------------------------------------------------ 2 passage B, leave-taking, review
_PAS_B = [("Woman", "Randy, ano’ng atin?", "Randy, what’s up?"), ("Man", "Wala lang. Eh, ikaw, saan ang lakad?", "Nothing, really. And you, where are you going?"), ("Woman", "Diyan lang.", "Just over there."), ("Man", "O sige, ingat ka. Hanggang sa susunod.", "All right, take care. Until next time."), ("Woman", "Ingat din. Hanggang sa Linggo.", "You too. Until Sunday.")]
_VB = [("Ano’ng atin?", "What’s up?"), ("Wala lang.", "Nothing."), ("Saan ang lakad?", "Where are you going?"), ("Diyan lang.", "Literally: There only."), ("Ingat.", "Take care."), ("o sige", "OK, alright"), ("Hanggang sa susunod.", "Until next time."), ("Hanggang sa isang linggo.", "Until next week.")]
_LEAVE = [("hanggang sa Lunes", "until Monday"), ("hanggang bukas", "until tomorrow"), ("hanggang sa Linggo", "until Sunday"), ("hanggang sa muli", "until next time")]
_REVG = [("Kamusta po kayo?", "How are you, sir/ma’am?", "Greeting"), ("Ano’ng atin?", "What’s up?", "Greeting"), ("Saan ang lakad?", "Where are you going?", "Greeting"), ("O, sige.", "All right (implies saying goodbye)", "Leave-taking"), ("Hanggang sa susunod.", "Until next time.", "Leave-taking"), ("Hanggang sa isang linggo.", "Until next week.", "Leave-taking"), ("Mano po.", "Bless me, mom, dad, aunt, uncle and so on.", "Courtesy"), ("Halikayo, kumain tayo.", "Come, let’s eat.", "Courtesy"), ("Ingat ka.", "Take care.", "Courtesy"), ("Ingat ka din.", "Take care, too.", "Courtesy")]
_ACT5 = [("A", "O, Badong, kamusta ka?", "Badong, how are you?"), ("B", "O, Ana. Mabuti. Ikaw, kamusta?", "Ana. Fine. And you, how are you?"), ("A", "OK lang. Ano’ng atin?", "Okay. What’s up?"), ("B", "Wala lang. E, ikaw, saan ang lakad?", "Nothing. And you, where are you going?"), ("A", "Diyan lang.", "Just over there."), ("B", "O, sige, ingat ka. Hanggang sa susunod.", "All right, take care. Until next time."), ("A", "Ingat din.", "You too.")]
_TRANS = [("Ano’ng atin?", "What’s up?"), ("Ikaw, saan ang lakad?", "How about you, where are you going?"), ("Kamusta kayo?", "How are you?"), ("Sino sila?", "Who are they?"), ("Ayos lang po kami.", "We are okay, sir/ma’am.")]
_TRS = [("Mano po, ’Nay.", "Bless me, Mother."), ("Sila po ang mga kaibigan ko.", "They are my friends, sir/ma’am."), ("Hanggang sa isang linggo.", "Until next week."), ("Halikayo, kumain tayo.", "Come, let’s eat."), ("Ikaw, saan ang lakad?", "You, where are you going?")]
L2 = lesson(
    "C1 L5 · Greetings and leave-taking between friends and officemates",
    "Ano’ng atin? · Saan ang lakad? · Diyan lang · Ingat ka · Hanggang sa susunod",
    requires=[],
    cards=[
        card("Passage B: officemates greet each other and say goodbye", "", examples=dlg(_PAS_B)),
        card("Culture note: Ano’ng atin? and Saan ang lakad?", "A common greeting in Tagalog is Ano’ng atin? or Saan ang lakad? (or Saan ka pupunta? or Saan ang punta?), meaning “What’s up? Where are you going?”. It is an informal greeting equivalent to “Hello” or “Hi” and is not meant to find out information. A vague Diyan lang (contracted D’yan lang, “Just there”), Wala lang (“Nothing, really”), a smile or a raising of the eyebrows to acknowledge the greeting is often enough of an answer."),
        card("Leave-taking expressions", "Hanggang sa susunod and hanggang sa isang linggo are leave-taking expressions. You can replace the time words with days of the week and other time words that you know.", tables=[ttable(_LEAVE)]),
        card("New words", "", tables=[ttable(_VB)]),
        card("Review: greetings, courtesies and leave-taking", "The book’s review table, with the translations filled in:", tables=[table(["Tagalog", "English", "Kind"], [list(r) for r in _REVG], say=[0])]),
        card("Passage B, comprehension check (the book’s key)", "Leave-taking expressions mentioned: OK, take care; until next time; until next week. Greetings mentioned: What’s up? Where are you going? Response mentioned: Nothing. Just there. Occupations in the demonstrative dialogs (Passage C, next lessons): student, teacher and soldier."),
        card("Dialog between two friends (Listening, Activity 5, the book’s script)", "The book asks you to list the greetings, courtesies and leave-taking expressions and translate them; the script is:", examples=dlg(_ACT5)),
        card("Translating and transcribing (FLO Skills, Activities 1 and 2, the book’s key)", "Transcription key: Mano po, ’Nay. Sila po ang mga kaibigan ko. Hanggang sa isang linggo. Halikayo, kumain tayo. Ikaw, saan ang lakad? Translation key:", tables=[table(["Tagalog", "English"], [list(r) for r in _TRANS + _TRS], say=[0])]),
        card("Activities left out", "Activity 3 (writing numerals from audio): the key is Tagalog 4, 6, 9, 10, 5 / 11, 15, 18, 19, 20 / 2, 1, 7, 8, 12 and Spanish 5, 8, 10, 9, 4 / 12, 14, 17, 18, 13 / 6, 7, 2, 0, 1. Also left out: the audio of Activity 5 and the speaking tasks of Activities 6 to 8."),
    ],
    exercises=uniq(
        both_q(_VB) + tr_q(_LEAVE) + rev_q(_LEAVE) + tr_q(_TRANS + _TRS) + rev_q(_TRANS + _TRS)
        + tr_q([(t, e) for _, t, e in _PAS_B]) + tr_q([(t, e) for _, t, e in _ACT5])
        + [M(f"Is {t} a greeting, a leave-taking or a courtesy?", k, dd(["Greeting", "Leave-taking", "Courtesy"], k), f"{t}: {k.lower()}.") for t, _, k in _REVG]
        + [M("How do you answer Ano’ng atin? informally?", "Wala lang.", ["Mano po.", "Hanggang sa susunod.", "Sino sila?"], "Wala lang, diyan lang, or just a smile."), M("Is Saan ang lakad? meant to get information?", "No, it is an informal greeting", ["Yes, always", "Only from teachers", "Only on the phone"], "It is like “Hi”."), M("What is a vague answer to Saan ang lakad?", "Diyan lang.", ["Mano po.", "Ingat din.", "Ayos lang po kami."], "Just there."), M("What does hanggang mean in hanggang bukas?", "until", ["after", "tomorrow", "next"], "hanggang = until."), M("How do you say “until Monday”?", "hanggang sa Lunes", ["hanggang bukas", "hanggang sa susunod", "hanggang sa Linggo"], "Replace the time word."), M("What does Ingat ka din mean?", "Take care, too.", ["Come, let’s eat.", "Where are you going?", "Bless me."], "Din = too, also."), M("What does o sige imply?", "That the person is saying goodbye", ["That the person is asking a question", "That the person is angry", "That the person is introducing someone"], "O sige can be a goodbye."), M("What other expressions can replace Saan ang lakad?", "Saan ka pupunta? and Saan ang punta?", ["Mano po and Ingat", "Sino ka? and Ano ka?", "Kamusta ka? and Ano ang pangalan mo?"], "Both mean “Where are you going?”.")]
        + [F("Ano’ng ___? (what’s up)", "atin", ["lakad", "oras"], "Ano’ng atin?"), F("Saan ang ___? (where are you going)", "lakad", ["atin", "susunod"], "Saan ang lakad?"), F("___ lang. (nothing)", "Wala", ["Diyan", "Ayos"], "Wala lang."), F("Hanggang sa ___. (next time)", "susunod", ["lakad", "atin"], "Hanggang sa susunod."), F("Ingat ___. (take care, you)", "ka", ["kami", "sila"], "Ingat ka."), F("Ingat ___. (you too)", "din", ["lang", "po"], "Ingat din.")]
    ),
)

# ------------------------------------------------------------------ 3 Set I personal pronouns
_PRON = [("ako", "I", "1st person singular"), ("kami", "we (exclusive: does not include the person spoken to)", "1st person plural"), ("tayo", "we (inclusive: includes the person spoken to)", "1st person plural"), ("ka", "you (singular)", "2nd person singular"), ("ikaw", "you (singular)", "2nd person singular"), ("kayo", "you (plural), or you (singular, polite)", "2nd person plural"), ("siya", "he, she", "3rd person singular"), ("sila", "they (plural), or they (singular, polite)", "3rd person plural")]
_AMER = [("Ikaw ay Amerikano.", "You are an American.", "Amerikano ka."), ("Siya ay Amerikano.", "He or she is an American.", "Amerikano siya."), ("Kami ay Amerikano.", "We are Americans (exclusive).", "Amerikano kami."), ("Tayo ay Amerikano.", "We are Americans (inclusive).", "Amerikano tayo."), ("Kayo ay Amerikano.", "You are Americans.", "Amerikano kayo."), ("Sila ay Amerikano.", "They are Americans.", "Amerikano sila."), ("Ako ay Amerikano.", "I am an American.", "Amerikano ako.")]
_PAS_EX = [("Kaawaan ka ng Diyos, anak.", "God bless you, child."), ("Ikaw, saan ang lakad?", "You, where are you going?"), ("Sino ang Amerikano? Ikaw.", "Who is the American? You."), ("Ayos lang kami.", "We are fine. (kami: the speaker and friends, excluding the person spoken to)"), ("Halikayo, kumain tayo.", "Come, let’s eat. (tayo: the mother, Liz and her friends together)"), ("Siya ay Pilipino.", "He or she is a Filipino."), ("Sino po sila?", "Who is it, please? (said politely, for example by a receptionist to a client)"), ("Sino sila?", "Who are they?")]
L3 = lesson(
    "C1 L5 · Set I personal pronouns",
    "ako, ka, ikaw, siya · kami and tayo · kayo, sila · Amerikano ka. · Amerikano sila.",
    requires=[],
    cards=[
        card("The pronouns", "A pronoun substitutes for a noun. Set I pronouns are distinguished by person (first, second, third) and by number.", tables=[table(["Tagalog", "English", "Person and number"], [list(r) for r in _PRON], say=[0])]),
        card("Using the pronouns in sentences", "Any pronoun can replace the subject: Ako ay Amerikano becomes Ikaw ay Amerikano, Siya ay Amerikano, Kami ay Amerikano, Tayo ay Amerikano, Kayo ay Amerikano or Sila ay Amerikano. In the predicate + subject order, which is common in conversation, you say Amerikano ako, Amerikano ka, Amerikano siya, Amerikano kami, Amerikano tayo, Amerikano kayo, Amerikano sila.", tables=[table(["Subject + ay + predicate", "English", "Predicate + subject"], [list(r) for r in _AMER], say=[0, 2])]),
        card("Rule 1: ka and ikaw", "There are two forms of “you, singular”. Ka is never used to start a sentence, while ikaw can. It is wrong to say Ka Amerikano; say Amerikano ka. Ikaw can stand alone as a short answer, but ka cannot: Sino ang Amerikano? Ikaw.", examples=passage([("Amerikano ka.", "You are American."), ("Ikaw, saan ang lakad?", "You, where are you going?"), ("Kaawaan ka ng Diyos, anak.", "God bless you, child.")])),
        card("Rule 2: kami and tayo", "In the first person plural, “we” has two forms. Kami (exclusive) leaves out the person being spoken to; tayo (inclusive) includes that person. In Passage A, Liz says Ayos lang kami (we are fine: herself and her friends, excluding the mother), and the mother says Halikayo, kumain tayo (come, let’s eat: herself, Liz and her friends).", examples=passage([("Ayos lang kami.", "We are fine."), ("Halikayo, kumain tayo.", "Come, let’s eat.")])),
        card("Rule 3: siya and sila", "Siya is a genderless pronoun and may refer to a man or a woman. Sila means “they” (third person plural), and it may also be singular and polite: on the telephone a receptionist often asks a client Sino po sila? (literally “Who are they?”) to be courteous. In Passage A, sila refers to the plural “they”.", examples=passage(_PAS_EX[5:])),
        card("Examples from the reading", "", examples=passage(_PAS_EX)),
        card("Listening activity (Activity 4, the book’s script and key)", "Nine sentences, with the Set I pronoun in each: kayo (polite), kayo (plural), tayo (inclusive), kami (exclusive), ikaw, ka, siya, ako, sila.", examples=passage([("Kamusta po kayo, ’Nay?", "How are you, Mother? (kayo, polite)"), ("Kayo ang mga guro.", "You are the teachers. (kayo, plural)"), ("Halikayo. Kain tayo.", "Come. Let’s eat. (tayo, inclusive)"), ("Ayos lang po kami.", "We are fine, sir/ma’am. (kami, exclusive)"), ("Ikaw ang sundalo.", "You are the soldier. (ikaw)"), ("O, sige, ingat ka.", "All right, take care. (ka)"), ("Sino siya?", "Who is he or she? (siya)"), ("Pilipino ako.", "I am Filipino. (ako)"), ("Sila ang mga guro.", "They are the teachers. (sila)")])),
        card("Activities left out", "The audio of Activity 4."),
    ],
    exercises=uniq(
        tr_q([(a, b) for a, b, _ in _PRON]) + rev_q([(a, b) for a, b, _ in _PRON if a not in ("ka", "ikaw")])
        + tr_q([(a, b) for a, b, _ in _AMER]) + tr_q([(c, b) for _, b, c in _AMER])
        + [M(f"How do you say “{b}” with the predicate first?", c, [x for _, _, x in _AMER if x != c][:3], f"{c}") for _, b, c in _AMER]
        + [M("Which pronoun cannot start a sentence?", "ka", ["ikaw", "kayo", "siya"], "Ka is never used to start a sentence."), M("Which pronoun can stand alone as a short answer?", "ikaw", ["ka", "ako ka", "mo"], "Ikaw can; ka cannot."), M("Which is wrong?", "Ka Amerikano.", ["Amerikano ka.", "Ikaw ay Amerikano.", "Ikaw, saan ang lakad?"], "Say Amerikano ka."), M("Which “we” leaves out the person spoken to?", "kami", ["tayo", "sila", "kayo"], "Kami is exclusive."), M("Which “we” includes the person spoken to?", "tayo", ["kami", "sila", "kayo"], "Tayo is inclusive."), M("The mother says Halikayo, kumain tayo. Why tayo?", "It includes herself and the guests", ["It leaves out the guests", "It means “they”", "It means “I”"], "Inclusive we."), M("Liz says Ayos lang kami. Why kami?", "It leaves out the mother", ["It includes the mother", "It means “you”", "It means “they”"], "Exclusive we."), M("Is siya masculine or feminine?", "Neither; it can be a man or a woman", ["Masculine only", "Feminine only", "Plural"], "Siya is genderless."), M("Why does a receptionist say Sino po sila?", "Sila is used to be polite to one person", ["It means “we”", "It means “you, plural”", "It is a mistake"], "Polite singular sila."), M("How many people does kayo refer to?", "More than one, or one person politely", ["Always one", "Always two", "Always three"], "Kayo is plural or singular polite."), M("Which is the plural of “you” or the polite “you”?", "kayo", ["ka", "ikaw", "ako"], "Kayo."), M("Who is the American, if you mean the person you are speaking to?", "Ikaw.", ["Ka.", "Ako.", "Kayo ka."], "Ikaw can stand alone.")]
        + [F("Amerikano ___. (you)", "ka", ["ikaw", "ako"], "Amerikano ka."), F("___ ay Amerikano. (you)", "Ikaw", ["Ka", "Ako"], "Ikaw can start a sentence."), F("Halikayo, kumain ___. (inclusive we)", "tayo", ["kami", "kayo"], "Tayo."), F("Ayos lang ___. (exclusive we)", "kami", ["tayo", "sila"], "Kami."), F("Sino po ___? (polite)", "sila", ["kami", "ako"], "Sino po sila?"), F("Pilipino ___. (I)", "ako", ["ka", "kayo"], "Pilipino ako."), F("Amerikano ___. (he or she)", "siya", ["sila", "ka"], "Amerikano siya.")]
    ),
)

# ------------------------------------------------------------------ 4 Set I demonstratives, practice, glossary
_DEM = [("ito", "this (near the speaker)", "singular"), ("ang mga ito", "these (near the speaker)", "plural"), ("iyan", "that (near the person spoken to)", "singular"), ("ang mga iyan", "those (near the person spoken to)", "plural"), ("iyon", "that over there (far from both)", "singular"), ("ang mga iyon", "those over there (far from both)", "plural")]
_PAS_C = [("Sino ito?", "Who is this person?"), ("Estudyante iyan.", "He or she is a student."), ("Sino ang mga ito?", "Who are these people?"), ("Mga sundalo ang mga iyan.", "Those are soldiers."), ("Sino iyon?", "Who is that person over there?"), ("Mga guro ang mga iyon.", "Those persons over there are teachers.")]
_DEMQ = [("Sino ito?", "Estudyante iyan."), ("Sino ang mga ito?", "Mga sundalo ang mga iyan."), ("Sino iyon?", "Mga guro iyon.")]
